{"t":"say","text":"I'll draw a RAG chatbot architecture: users reach ESA, an ALB routes to ACK running Dify, which queries Model Studio and Milvus."}
{"t":"plan","products":["users","dns","esa","alb","waf","ack","dify-on-ack","model-studio","milvus","oss","tair","rds","sls"]}
{"t":"group","id":"internet","kind":"external","label":"Internet","parent":null}
{"t":"node","id":"users","product":"users","label":"Website visitors","group":"internet","why":"Customers asking support questions on the website."}
{"t":"node","id":"dns","product":"dns","label":"Cloud DNS","group":null,"why":"Resolves the chatbot domain to ESA."}
{"t":"edge","id":"e-users-dns","from":"users","to":"dns","kind":"resolve"}
{"t":"group","id":"edge","kind":"edge","label":"Edge","parent":null}
{"t":"node","id":"esa","product":"esa","label":"ESA","group":"edge","why":"Accelerates and secures chat traffic at the edge."}
{"t":"edge","id":"e-users-esa","from":"users","to":"esa","label":"HTTPS"}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"Chatbot VPC","parent":"sg"}
{"t":"node","id":"alb","product":"alb","label":"ALB","group":"vpc","zones":["a","b"],"why":"Routes incoming chat requests to the ACK cluster."}
{"t":"node","id":"waf","product":"waf","label":"WAF","group":"vpc","attachTo":"alb","why":"Blocks injection attacks and bots before the app."}
{"t":"edge","id":"e-esa-alb","from":"esa","to":"alb","label":"origin"}
{"t":"node","id":"ack","product":"ack","label":"ACK cluster","group":"vpc","zones":["a","b"],"why":"Runs the Dify containers across two zones."}
{"t":"edge","id":"e-alb-ack","from":"alb","to":"ack"}
{"t":"node","id":"dify","product":"dify-on-ack","label":"Dify on ACK","group":"vpc","attachTo":"ack","why":"Orchestrates RAG pipelines, prompts and chat sessions."}
{"t":"say","text":"Dify retrieves chunks from Milvus, calls Qwen models via Model Studio, and stores state in Tair and RDS."}
{"t":"node","id":"vector","product":"milvus","label":"Milvus vector store","group":"vpc","zones":["a","b"],"why":"Holds embeddings of product docs for retrieval."}
{"t":"edge","id":"e-ack-vector","from":"ack","to":"vector","label":"search"}
{"t":"node","id":"llm","product":"model-studio","label":"Model Studio","group":"sg","why":"Provides Qwen models to generate answers from context."}
{"t":"edge","id":"e-ack-llm","from":"ack","to":"llm","label":"LLM API"}
{"t":"node","id":"cache","product":"tair","label":"Session cache","group":"vpc","zones":["a","b"],"why":"Caches conversation state and frequent lookups."}
{"t":"edge","id":"e-ack-cache","from":"ack","to":"cache"}
{"t":"node","id":"db","product":"rds","label":"Metadata DB","group":"vpc","zones":["a","b"],"why":"Stores Dify metadata, configs and chat history."}
{"t":"edge","id":"e-ack-db","from":"ack","to":"db","label":"SQL"}
{"t":"node","id":"docs","product":"oss","label":"Doc bucket","group":"sg","why":"Stores raw help-center articles and product PDFs."}
{"t":"edge","id":"e-ack-docs","from":"ack","to":"docs","label":"ingest"}
{"t":"node","id":"logs","product":"sls","label":"Logs","group":"sg","why":"Collects chat logs and traces for monitoring."}
{"t":"edge","id":"e-ack-logs","from":"ack","to":"logs","kind":"control"}
{"t":"done","summary":"RAG chatbot with ESA, ALB+WAF, Dify on ACK, Milvus for vectors, Model Studio for Qwen, plus Tair, RDS, OSS and SLS."}

{"t":"say","text":"I'll draw an enterprise AI agent platform using AgentCore for governance, AgentRun for runtime, and AI Gateway for model routing."}
{"t":"req","text":"Enterprise AI agents with MCP tools and human approval steps"}
{"t":"plan","products":["users","agentcore","agentrun","ai-gateway","model-studio","agent-security-center","ai-guardrails","sls","ram"]}
