{"t":"edge","id":"e-agentrun-ai-gateway","from":"agentrun","to":"ai-gateway","label":"LLM"}
{"t":"node","id":"model-studio","product":"model-studio","label":"Model Studio","group":"sg","why":"Provides Qwen and third-party model APIs."}
{"t":"edge","id":"e-ai-gateway-model-studio","from":"ai-gateway","to":"model-studio","label":"API"}
