{"t":"say","text":"I'll draw a RAG assistant architecture: employees query an AgentCore agent that retrieves answers from your docs via Model Studio and a vector store."}
{"t":"plan","products":["users","agentcore","model-studio","milvus","oss","sls"]}
{"t":"group","id":"internet","kind":"external","label":"Internal users","parent":null}
{"t":"node","id":"users","product":"users","label":"Employees","group":"internet","why":"Staff asking policy and wiki questions."}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"node","id":"agentcore","product":"agentcore","label":"AgentCore","group":"sg","why":"Hosts the RAG agent with skills and MCP tools for employees."}
{"t":"edge","id":"e-users-agentcore","from":"users","to":"agentcore","label":"chat"}
