{"t":"say","text":"I'll draw a hardened e-commerce edge with Anti-DDoS Proxy, ESA, WAF and Captcha to stop bots and attacks."}
{"t":"plan","products":["users","dns","anti-ddos-proxy","esa","waf","captcha","alb","ecs","ess","tair","rds","oss","sls"]}
{"t":"group","id":"internet","kind":"external","label":"Internet","parent":null}
{"t":"node","id":"users","product":"users","label":"Shoppers & Bots","group":"internet","why":"Visitors including legitimate shoppers and attackers."}
{"t":"node","id":"dns","product":"dns","label":"Cloud DNS","group":null,"why":"Resolves the shop domain to Anti-DDoS Proxy."}
{"t":"edge","id":"e-users-dns","from":"users","to":"dns","kind":"resolve"}
