{"t":"node","id":"ddos","product":"anti-ddos-proxy","label":"Anti-DDoS Proxy","group":"edge","why":"Scrubbing center absorbs volumetric DDoS attacks before they reach the origin."}
{"t":"edge","id":"e-users-ddos","from":"users","to":"ddos","label":"HTTPS"}
{"t":"node","id":"esa","product":"esa","label":"ESA","group":"edge","why":"Caches static assets and provides bot management at the edge."}
